using System;
using UnityEngine;

[Serializable]
public struct WaveConfig
{
    [SerializeField] private int _enemyCount;

    public int EnemyCount => _enemyCount;

    public WaveConfig(int enemyCount)
    {
        _enemyCount = Mathf.Max(0, enemyCount);
    }
}

public class WaveSpawner : MonoBehaviour
{
    [SerializeField] private GameObject _enemyPrefab;
    [SerializeField] private Transform _spawnPoint;
    [SerializeField] private WaveConfig[] _waves;
    [SerializeField] private float _delayBetweenWaves = 5f;

    private int _nextWaveIndex;
    private float _timer;
    private float _timeUntilNextWave;
    private bool _isFinished;

    public event Action<int, int> WaveStarted;
    public event Action<GameObject> EnemySpawned;
    public event Action AllWavesCompleted;

    public bool IsFinished => _isFinished;
    public int TotalWaves => _waves?.Length ?? 0;
    public int WavesSpawned => _nextWaveIndex;

    private void Awake()
    {
        _delayBetweenWaves = Mathf.Max(0f, _delayBetweenWaves);

        if (_enemyPrefab == null)
        {
            Debug.LogError($"{nameof(WaveSpawner)} on '{name}' has no enemy prefab assigned.", this);
        }

        _nextWaveIndex = 0;
        _timer = 0f;
        _timeUntilNextWave = 0f;
        _isFinished = TotalWaves == 0;
    }

    // Driven externally so tests and game systems can advance waves deterministically.
    public void Tick(float deltaTime)
    {
        if (_isFinished) return;

        _timer += deltaTime;
        if (_timer < _timeUntilNextWave) return;

        _timer = 0f;
        SpawnWave(_nextWaveIndex);
        _nextWaveIndex++;
        _timeUntilNextWave = _delayBetweenWaves;

        if (_nextWaveIndex >= TotalWaves)
        {
            _isFinished = true;
            AllWavesCompleted?.Invoke();
        }
    }

    private void SpawnWave(int waveIndex)
    {
        int enemyCount = Mathf.Max(0, _waves[waveIndex].EnemyCount);
        WaveStarted?.Invoke(waveIndex, enemyCount);

        if (_enemyPrefab == null) return;

        Vector3 position = _spawnPoint != null ? _spawnPoint.position : transform.position;
        Quaternion rotation = _spawnPoint != null ? _spawnPoint.rotation : transform.rotation;

        for (int i = 0; i < enemyCount; i++)
        {
            GameObject enemy = Instantiate(_enemyPrefab, position, rotation);
            EnemySpawned?.Invoke(enemy);
        }
    }
}
