using System.Reflection;
using System.Text.RegularExpressions;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;

public class WaveSpawnerTests
{
    private static void SetPrivateField(object target, string fieldName, object value)
    {
        FieldInfo field = target.GetType().GetField(fieldName, BindingFlags.NonPublic | BindingFlags.Instance);
        field.SetValue(target, value);
    }

    private WaveSpawner CreateSpawner(WaveConfig[] waves, float delayBetweenWaves, GameObject enemyPrefab)
    {
        var go = new GameObject("WaveSpawner");
        go.SetActive(false);
        var spawner = go.AddComponent<WaveSpawner>();

        SetPrivateField(spawner, "_waves", waves);
        SetPrivateField(spawner, "_delayBetweenWaves", delayBetweenWaves);
        SetPrivateField(spawner, "_enemyPrefab", enemyPrefab);

        go.SetActive(true); // triggers Awake with the fields already wired
        return spawner;
    }

    [Test]
    public void FirstTick_SpawnsFirstWaveImmediately()
    {
        var prefab = new GameObject("EnemyPrefab");
        var waves = new[] { new WaveConfig(3) };
        var spawner = CreateSpawner(waves, 5f, prefab);

        int spawnedCount = 0;
        spawner.EnemySpawned += _ => spawnedCount++;

        spawner.Tick(0.016f);

        Assert.AreEqual(1, spawner.WavesSpawned);
        Assert.AreEqual(3, spawnedCount);
        Assert.IsFalse(spawner.IsFinished);

        Object.DestroyImmediate(spawner.gameObject);
        Object.DestroyImmediate(prefab);
    }

    [Test]
    public void Tick_DoesNotSpawnNextWave_BeforeDelayElapses()
    {
        var prefab = new GameObject("EnemyPrefab");
        var waves = new[] { new WaveConfig(1), new WaveConfig(1) };
        var spawner = CreateSpawner(waves, 2f, prefab);

        spawner.Tick(0.016f); // spawns wave 0
        spawner.Tick(1f);     // only 1s of the 2s delay has elapsed

        Assert.AreEqual(1, spawner.WavesSpawned);
        Assert.IsFalse(spawner.IsFinished);

        Object.DestroyImmediate(spawner.gameObject);
        Object.DestroyImmediate(prefab);
    }

    [Test]
    public void Tick_SpawnsNextWave_AfterDelayElapses_AndStopsAfterLastWave()
    {
        var prefab = new GameObject("EnemyPrefab");
        var waves = new[] { new WaveConfig(1), new WaveConfig(2) };
        var spawner = CreateSpawner(waves, 2f, prefab);

        bool allCompletedFired = false;
        spawner.AllWavesCompleted += () => allCompletedFired = true;

        int spawnedCount = 0;
        spawner.EnemySpawned += _ => spawnedCount++;

        spawner.Tick(0.016f); // wave 0: 1 enemy
        spawner.Tick(1f);
        spawner.Tick(1f);     // 2s elapsed -> wave 1: 2 enemies, last wave

        Assert.AreEqual(2, spawner.WavesSpawned);
        Assert.AreEqual(3, spawnedCount);
        Assert.IsTrue(spawner.IsFinished);
        Assert.IsTrue(allCompletedFired);

        spawner.Tick(10f); // must be a no-op after finishing
        Assert.AreEqual(3, spawnedCount);
        Assert.AreEqual(2, spawner.WavesSpawned);

        Object.DestroyImmediate(spawner.gameObject);
        Object.DestroyImmediate(prefab);
    }

    [Test]
    public void NoWavesConfigured_IsFinishedImmediately_AndTickIsNoOp()
    {
        var prefab = new GameObject("EnemyPrefab");
        var spawner = CreateSpawner(new WaveConfig[0], 2f, prefab);

        Assert.IsTrue(spawner.IsFinished);

        int spawnedCount = 0;
        spawner.EnemySpawned += _ => spawnedCount++;
        spawner.Tick(5f);

        Assert.AreEqual(0, spawnedCount);
        Assert.AreEqual(0, spawner.WavesSpawned);

        Object.DestroyImmediate(spawner.gameObject);
        Object.DestroyImmediate(prefab);
    }

    [Test]
    public void WaveConfig_ClampsNegativeEnemyCountToZero()
    {
        var wave = new WaveConfig(-5);
        Assert.AreEqual(0, wave.EnemyCount);
    }

    [Test]
    public void MissingEnemyPrefab_LogsError_ButStillAdvancesWaves()
    {
        var waves = new[] { new WaveConfig(2) };

        LogAssert.Expect(LogType.Error, new Regex(".*enemy prefab.*"));
        var spawner = CreateSpawner(waves, 1f, null);

        bool waveStartedFired = false;
        int reportedEnemyCount = -1;
        spawner.WaveStarted += (index, count) =>
        {
            waveStartedFired = true;
            reportedEnemyCount = count;
        };

        Assert.DoesNotThrow(() => spawner.Tick(0.016f));
        Assert.IsTrue(waveStartedFired);
        Assert.AreEqual(2, reportedEnemyCount);
        Assert.AreEqual(1, spawner.WavesSpawned);

        Object.DestroyImmediate(spawner.gameObject);
    }
}
